<?php
require 'config.php'; require_role('student'); $u=$_SESSION['user'];$title='Enrollment Confirmation';$term=selected_term($pdo);$termId=$term?(int)$term['id']:0;
$q=$pdo->prepare("SELECT s.*,sub.code,sub.name,sub.units,o.section,o.faculty_id,f.name AS faculty_name FROM schedules s JOIN subjects sub ON sub.id=s.subject_id LEFT JOIN subject_offerings o ON o.subject_id=s.subject_id AND o.day_name=s.day_name AND o.start_time=s.start_time AND o.end_time=s.end_time AND o.room=s.room LEFT JOIN users f ON f.id=COALESCE(o.faculty_id,sub.faculty_id) WHERE s.student_id=? AND s.term_id=? ORDER BY FIELD(s.day_name,'Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'),s.start_time");$q->execute([$u['id'],$termId]);$rows=$q->fetchAll();$units=array_sum(array_map(fn($r)=>(int)$r['units'],$rows));$estimate=$units*PROTOTYPE_TUITION_PER_UNIT+($units?PROTOTYPE_MISC_FEE:0);
require 'header.php';?><div class="section printable"><div class="section-intro"><div><span class="eyebrow">ETW – NU BALIWAG ONLINE MANAGEMENT SYSTEM</span><h2>Enrollment Confirmation</h2><p class="muted"><?=e($term['label']??'Academic Term')?> · Student enrollment summary</p></div><div class="button-group no-print"><button class="btn" onclick="window.print()">Print / Save as PDF</button><a class="btn" href="download_confirmation.php?term=<?=e($term['term_key']??'')?>">Download C.O.R. (PDF)</a></div></div><div class="confirmation-student"><div><span>Student Name</span><b><?=e($u['name'])?></b></div><div><span>Student ID</span><b><?=e($u['student_id']?:'—')?></b></div><div><span>Program</span><b><?=e($u['program']?:'—')?></b></div><div><span>Total Units</span><b><?=e($units)?></b></div></div><div class="assessment-box"><div><span>Estimated Tuition / Assessment</span><strong><?=money($estimate)?></strong></div><small>Prototype estimate only: <?=money(PROTOTYPE_TUITION_PER_UNIT)?> per unit + <?=money(PROTOTYPE_MISC_FEE)?> miscellaneous fee.</small></div><div class="table-scroll"><table class="table"><tr><th>Subject</th><th>Units</th><th>Schedule</th><th>Teacher</th><th>Section / Room</th></tr><?php foreach($rows as $r):?><tr><td><a href="subject_details.php?id=<?=e($r['subject_id'])?>"><b><?=e($r['code'])?></b></a><br><small><?=e($r['name'])?></small></td><td><?=e($r['units'])?></td><td><?=e($r['day_name'])?><br><?=date('g:i A',strtotime($r['start_time']))?> – <?=date('g:i A',strtotime($r['end_time']))?></td><td><?=e($r['faculty_name']??'Assigned Faculty')?></td><td><?=e($r['section']??'—')?> / <?=e($r['room'])?></td></tr><?php endforeach;?></table></div><p class="muted confirmation-note">This document is a prototype enrollment confirmation generated by ETW – NU Baliwag Online Management System.</p></div><?php require 'footer.php';?>
